cat /app/resources/treasury_bulletin_1980_03.json | python3 -c "
import json,sys
d=json.load(sys.stdin)
pages = d.get('document', {}).get('pages', [])
for i, page in enumerate(pages[:5]):
    print(f'--- Page {i} ---')
    print('Keys:', page.keys())
    if 'elements' in page:
        for el in page['elements'][:3]:
            print('Element type:', el.get('type'))
            if el.get('type') == 'table':
                print('Table data sample:', str(el)[:500])
